-- JEM 5.1.0: stable registration identity and append-only history.
-- PHP postflight performs the idempotent reference and baseline-history
-- backfill before registration writes are enabled.

ALTER TABLE `#__jem_register` ADD COLUMN `reference` VARCHAR(28) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL AFTER `comment` /** CAN FAIL **/;
ALTER TABLE `#__jem_register` ADD COLUMN `created` DATETIME NULL DEFAULT NULL AFTER `reference` /** CAN FAIL **/;
ALTER TABLE `#__jem_register` ADD COLUMN `modified` DATETIME NULL DEFAULT NULL AFTER `created` /** CAN FAIL **/;
ALTER TABLE `#__jem_register` ADD COLUMN `revision` INT(10) UNSIGNED NOT NULL DEFAULT '1' AFTER `modified` /** CAN FAIL **/;

CREATE TABLE IF NOT EXISTS `#__jem_registration_history` (`id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT, `operation_reference` VARCHAR(28) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `registration_id` INT(11) UNSIGNED NOT NULL, `registration_reference` VARCHAR(28) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `revision` INT(10) UNSIGNED NOT NULL, `event_id` INT(11) UNSIGNED NOT NULL DEFAULT '0', `event_title` VARCHAR(255) NOT NULL DEFAULT '', `action` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `old_status` TINYINT(3) NULL DEFAULT NULL, `new_status` TINYINT(3) NULL DEFAULT NULL, `old_places` INT(11) NULL DEFAULT NULL, `new_places` INT(11) NULL DEFAULT NULL, `old_user_id` INT(11) NULL DEFAULT NULL, `new_user_id` INT(11) NULL DEFAULT NULL, `actor_user_id` INT(11) UNSIGNED NOT NULL DEFAULT '0', `source` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', `reason_code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL, `forced` TINYINT(1) NOT NULL DEFAULT '0', `changed_fields` TEXT NULL DEFAULT NULL, `occurred` DATETIME NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `idx_history_registration_revision` (`registration_id`,`revision`), UNIQUE KEY `idx_history_operation_registration` (`operation_reference`,`registration_id`), KEY `idx_history_reference_occurred` (`registration_reference`,`occurred`), KEY `idx_history_operation` (`operation_reference`), KEY `idx_history_event_occurred` (`event_id`,`occurred`), KEY `idx_history_actor_occurred` (`actor_user_id`,`occurred`), KEY `idx_history_action_occurred` (`action`,`occurred`), KEY `idx_history_source_occurred` (`source`,`occurred`), KEY `idx_history_status_occurred` (`new_status`,`occurred`), KEY `idx_history_occurred` (`occurred`)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `#__jem_notifications` (`id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT, `notification_uuid` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `registration_id` INT(11) UNSIGNED NOT NULL DEFAULT '0', `registration_reference` VARCHAR(28) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', `event_id` INT(11) UNSIGNED NOT NULL DEFAULT '0', `ticket_id` BIGINT(20) UNSIGNED NULL DEFAULT NULL COMMENT 'Reserved for a future individual ticket/QR phase', `notification_type` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `recipient_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'user', `recipient_user_id` INT(11) UNSIGNED NOT NULL DEFAULT '0', `recipient_name` VARCHAR(255) NOT NULL DEFAULT '', `recipient_email` VARCHAR(320) NOT NULL, `requested_language` VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', `resolved_language` VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'en-GB', `language_source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'fallback', `fallback_reason` VARCHAR(255) NOT NULL DEFAULT '', `template_id` VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', `subject` TEXT NOT NULL, `body` MEDIUMTEXT NOT NULL, `htmlbody` MEDIUMTEXT NULL DEFAULT NULL, `payload_json` MEDIUMTEXT NULL DEFAULT NULL, `attachments_json` MEDIUMTEXT NULL DEFAULT NULL COMMENT 'Reserved for a future individual ticket/PDF phase', `content_hash` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `state` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'queued', `scheduled_at` DATETIME NULL DEFAULT NULL, `queued_at` DATETIME NULL DEFAULT NULL, `processing_started_at` DATETIME NULL DEFAULT NULL, `sent_at` DATETIME NULL DEFAULT NULL, `failed_at` DATETIME NULL DEFAULT NULL, `cancelled_at` DATETIME NULL DEFAULT NULL, `next_attempt_at` DATETIME NULL DEFAULT NULL, `attempt_count` INT(10) UNSIGNED NOT NULL DEFAULT '0', `max_attempts` INT(10) UNSIGNED NOT NULL DEFAULT '4', `idempotency_key` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `resend_of` BIGINT(20) UNSIGNED NULL DEFAULT NULL, `source` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', `created_by` INT(11) UNSIGNED NOT NULL DEFAULT '0', `created` DATETIME NOT NULL, `modified` DATETIME NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `idx_notification_uuid` (`notification_uuid`), UNIQUE KEY `idx_notification_idempotency` (`idempotency_key`), KEY `idx_notification_registration_created` (`registration_id`,`created`), KEY `idx_notification_reference_created` (`registration_reference`,`created`), KEY `idx_notification_event_created` (`event_id`,`created`), KEY `idx_notification_recipient_created` (`recipient_user_id`,`created`), KEY `idx_notification_email_created` (`recipient_email`(191),`created`), KEY `idx_notification_state_attempt` (`state`,`next_attempt_at`), KEY `idx_notification_resend_of` (`resend_of`), KEY `idx_notification_created` (`created`)) ENGINE=InnoDB;

ALTER TABLE `#__jem_notifications` ADD COLUMN `registration_revision` INT(10) UNSIGNED NOT NULL DEFAULT '0' AFTER `registration_reference`;

CREATE TABLE IF NOT EXISTS `#__jem_notification_attempts` (`id` BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT, `notification_id` BIGINT(20) UNSIGNED NOT NULL, `attempt_number` INT(10) UNSIGNED NOT NULL, `transport` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'mail', `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'automatic', `requested_by_user_id` INT(11) UNSIGNED NOT NULL DEFAULT '0', `started_at` DATETIME NOT NULL, `finished_at` DATETIME NULL DEFAULT NULL, `result` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'processing', `transport_message_id` VARCHAR(255) NOT NULL DEFAULT '', `error_code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', `error_message` VARCHAR(1000) NOT NULL DEFAULT '', PRIMARY KEY (`id`), UNIQUE KEY `idx_attempt_notification_number` (`notification_id`,`attempt_number`), KEY `idx_attempt_notification_started` (`notification_id`,`started_at`), KEY `idx_attempt_result_started` (`result`,`started_at`)) ENGINE=InnoDB;

